let assessmentState=null, assessmentRequestKey=crypto.randomUUID();
const assessmentRoute=()=>['#assessment','#proctor'].includes(location.hash);
const beforeAssessment=render;
render=function(){
 if(!assessmentRoute())return beforeAssessment();
 document.getElementById('app').innerHTML=integratedShell('assessment',heading('Proctored assessment setup','Scholarion Academy · Prepare before test day')+'<section class="card prose"><p id="assessment-status" role="status">Loading your readiness checklist…</p><div id="assessment-content"></div></section>',model.role);bind();normalizeWorkspace();assessmentLoad();
};
async function assessmentLoad(){
 try{
 workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';
 const d=await workspaceApi('assessment-support/get');if(!assessmentRoute())return;assessmentState=d;normalizeWorkspace();
 document.getElementById('assessment-status').textContent=d.guidanceStatus;
 document.getElementById('assessment-content').innerHTML=`<label>Course<select id="assessment-course">${workspaceSession.courses.map(c=>`<option ${c===selectedCourse?'selected':''}>${esc(c)}</option>`).join('')}</select></label><h2>Webcam · Valid ID · Testing area</h2><p>Test a stable camera position that shows your face, hands and workspace. Prepare a current government-issued photo ID and remove unapproved devices from your testing area.</p><p>The full Assessment Policy, accessibility office, support contact and response time are not configured. These are draft talking points supplied for review.</p><h2>Your readiness checklist</h2><p>Self-reported only. Saving does not approve or schedule an assessment. No camera, microphone, ID image or room recording is collected here.</p><form id="assessment-save">${d.items.map((x,i)=>`<label style="display:block;margin:12px 0"><input type="checkbox" name="check" value="${i}" ${d.checks.includes(i)?'checked':''}> ${esc(x)}</label>`).join('')}<button class="button">Save readiness check</button></form><h2>Setup support assistant</h2><p>Choose a topic. This helper cannot review assessment content, grant exceptions or decide incidents.</p><label>Topic<select id="assessment-topic">${Object.keys(d.answers).map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><p id="assessment-answer" aria-live="polite">${esc(d.answers.Webcam)}</p><h3>Accessibility and accommodations</h3><p>Request review well before test day if assistive technology or camera placement creates a conflict. Do not share diagnoses or medical details. This helper cannot approve or deny accommodations.</p><button class="button secondary" id="assessment-escalate">Request staff support for this topic</button><p>Creates a private request in this local course’s Support module. No external forwarding or response-time promise is available.</p><a href="#help">View support requests and staff replies</a>`;
 }catch(e){if(assessmentRoute())document.getElementById('assessment-status').textContent=e.message+' — Sign in through Workspace account to save readiness and request support.';}
}
document.addEventListener('change',e=>{if(e.target.id==='assessment-course'){selectedCourse=e.target.value;assessmentRequestKey=crypto.randomUUID();render();}if(e.target.id==='assessment-topic'){document.getElementById('assessment-answer').textContent=assessmentState.answers[e.target.value];assessmentRequestKey=crypto.randomUUID();}});
document.addEventListener('submit',async e=>{if(e.target.id!=='assessment-save')return;e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await workspaceApi('assessment-support/save',{checks:[...e.target.querySelectorAll('input:checked')].map(x=>Number(x.value)),revision:assessmentState.revision});assessmentState.revision=r.revision;document.getElementById('assessment-status').textContent='Readiness saved to your course record. This is not assessment approval.';}catch(err){document.getElementById('assessment-status').textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{if(e.target.id!=='assessment-escalate')return;const b=e.target;b.disabled=true;try{const r=await workspaceApi('assessment-support/escalate',{topic:document.getElementById('assessment-topic').value,requestKey:assessmentRequestKey});document.getElementById('assessment-status').textContent='Local support request saved: '+r.id+'. View Support for replies. It has not been sent externally.';}catch(err){document.getElementById('assessment-status').textContent=err.message;}finally{b.disabled=false;}});
render();
